css:
.il { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; border-bottom: 1px solid rgba(255,255,255,0.1); }
.il-i { display: flex; flex-direction: column; gap: 6px; padding: 20px 0; border-top: 1px solid rgba(255,255,255,0.1); }
.il-t { font-size: 17px; font-weight: 600; color: #f4fbff; }
.il-d { font-size: 15px; line-height: 1.6; color: #9fb4c6; }
.il-n { font-size: 14px; line-height: 1.6; color: #8da2b5; }
.il-n a { color: #00cdfd; }
